window.AUTH=window.AUTH||{};window.AUTH["21-468"]={"d":"21-468","id":"2022/21-468","n":"National Pork Producers Council v. Ross","briefs":[{"k":"petitioner","label":"Brief of petitioners National Pork Producers Council, et al.","date":"2022-06-10","url":"https://www.supremecourt.gov/DocketPDF/21/21-468/227679/20220610132221228_Natl%20Pork%20Producers%20v%20Ross%20No.%2021-468%20Brief%20for%20Petitioners.pdf","side":"pet","n":50},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-06-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-468/228387/20220617195711500_No.%2021-468%20Natl%20Pork%20Producers%20v.%20Ross%20Final.pdf","side":"us","n":39},{"k":"respondent","label":"Brief of respondents The Humane Society of the United States, et al.","date":"2022-08-10","url":"https://www.supremecourt.gov/DocketPDF/21/21-468/233009/20220808170214770_Natl%20Pork%20Producers%20Council%20v.%20Ross%20--%20No.%2021-468%20--%20Intervenor%20Respondents%20Brief.pdf","side":"res","n":80},{"k":"united-states","label":"Brief amicus curiae of United States Senator Cory Booker","date":"2022-08-15","url":"https://www.supremecourt.gov/DocketPDF/21/21-468/233545/20220815161658282_Brief%20Of%20Amicus%20Curiae%20-%20US%20Sen.%20Cory%20Booker.pdf","side":"us","n":12},{"k":"reply","label":"Reply of petitioners National Pork Producers Council, et al.","date":"2022-09-07","url":"https://www.supremecourt.gov/DocketPDF/21/21-468/237235/20220907132411455_Natl%20Pork%20Producers%20v%20Ross%20No.%2021-468%20Reply%20Brief%20for%20Petitioners%20PDFA.pdf","side":"pet","n":30}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r18_g2bh.pdf","tr":true,"items":[{"t":"case","label":"Ableman v. Booth","cite":"62 U.S. 506","y":1858,"id":"1850-1900/62us506","sc":1,"sum":"The Court held that state courts do not have the authority to issue writs of habeas corpus in cases where the prisoner is held by the federal government.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"0":"2","1":"5","4":"1"}},{"t":"case","label":"Ass’n des Eleveurs de Canards et d’Oies du Quebec v. Harris","cite":"729 F.3d 937","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/729/937/","by":{"0":"21"}},{"t":"case","label":"Baldwin v. G.A.F. Selig, Inc.","cite":"294 U.S. 511","y":1935,"id":"1900-1940/294us511","sc":1,"op":17,"ar":20,"sum":"1. A law or regulation of a State which prohibits the sale of milk imported from another State unless the price paid in that other to the producer was up to the minimum prescribed by the first State for purchases from local producers, is a direct and unconstitutional burden on interstate commerce, whether applied to milk sold by the importer in the cans in which it was imported, or to milk sold by him in bottles in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 33, 37, 38","1":"passim","2":"passim","4":"7, 15, 16"}},{"t":"case","label":"Bonaparte v. Tax Court","cite":"104 U.S. 592","y":1882,"id":"scdb/1881-086","sc":1,"op":1,"sum":"The Constitution does not prohibit a State from including in the taxable property of her citizens so much of the registered public debt of another State as they respectively hold, although the debtor State may exempt it' from taxation or actually tax it.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Brennan v. City of Titusville","cite":"153 U.S. 289","y":1894,"id":"scdb/1893-234","sc":1,"sum":"—Decided April 30, 1894.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Brimmer v. Rebman","cite":"138 U.S. 78","y":1891,"id":"scdb/1890-091","sc":1,"sum":"A statute of Virginia, entitled ‘‘ An.act to prevent the selling of unwholesome meat,” approved February 18, 1890, (Laws of Virginia 1889-1890, 63 e. 80) declares it to be unlawful to offer for sale, within the limits of that State, any beef, veal or mutton, from animals slaughtered one hundred miles or more from the place at which it is offered for sale, unless it has been previously inspected and approved by local …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41","2":"36"}},{"t":"case","label":"Brown-Forman Distillers Corp. v. N.Y. State Liquor Auth.","cite":"476 U.S. 573","y":1986,"id":"1985/84-2030","sc":1,"op":13,"ar":4,"sum":"New York's Alcoholic Beverage Control Law (ABC Law) provides that a distiller, licensed to do business in the State, may not sell its products to wholesalers within the State except in accordance with a monthly price schedule previously filed with appellee State Liquor Authority, and requires that the distiller include with the schedule an affirmation that the prices in the schedule are no higher than the lowest …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 21, 22, 29","1":"2, 15, 16, 21, 33","2":"17, 18","4":"3, 6, 9"}},{"t":"case","label":"C&A Carbone, Inc. v. Town of Clarkston","cite":"511 U.S. 383","y":1994,"id":"1993/92-1402","sc":1,"op":2,"ar":5,"sum":"Tthe Court held 6-3 that the Commerce Clause invalidates local laws that discriminate against interstate commerce, disrupt the flow of articles of commerce, and grant municipalities disproportionate market gains.","sumSrc":"Oyez","by":{"0":"22, 26, 37, 39, 40","1":"11, 12, 20, 32","2":"14, 18, 19","4":"15, 21"}},{"t":"case","label":"Cal. Hisp. Chambers of Com. v. Ross","cite":"2022 Cal. Super. LEXIS 8135","y":2022,"court":"Jan. 21","by":{"0":"7"}},{"t":"case","label":"Camps Newfound/ Owatonna, Inc. v. Town of Harrison, Me.","cite":"520 U.S. 564","y":1997,"id":"1996/94-1988","sc":1,"op":4,"sum":"In a 5-to-4 opinion, the Court held that Maine's tax exemption statute violated the dormant commerce clause since it selectively awarded greater tax benefits to those institutions which served mostly state residents, while penalizing institutions that conducted mostly interstate business.","sumSrc":"Oyez","by":{"0":"24","4":"21"}},{"t":"case","label":"Central Hudson Gas & Electric v. Pub. Serv. Comm’n","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"City of Phila. v. New Jersey","cite":"437 U.S. 617","y":1978,"id":"1977/77-404","sc":1,"op":4,"sum":"The Court held that the law violated the principle of nondiscrimination as it treated out-of-state waste differently than waste produced within the state. Since New Jersey could not demonstrate a legitimate reason for distinguishing between foreign and domestically produced waste, it was clear to the Court that the state had \"overtly moved to slow or freeze the flow of commerce for protectionist reasons.\".","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Comptroller of Treasury of Maryland v. Wynne","cite":"575 U.S. 542","y":2015,"id":"2014/13-485","sc":1,"op":1,"sum":"The Court held that the dormant Commerce Clause prohibits the operation of Maryland’s tax scheme because it discriminates against interstate commerce.","sumSrc":"Oyez","by":{"0":"24, 27"}},{"t":"case","label":"Dep’t of Rev. of Ky. v. Davis","cite":"553 U.S. 328","y":2008,"id":"2007/06-666","sc":1,"op":12,"sum":"The Court held 7-2 that Kentucky's differential tax scheme does not offend the Commerce Clause. No single opinion commanded a majority. Bond proceeds are a \"quintessentially public function,\" the Court noted, and are therefore likely motivated by legitimate state objectives other than simple economic protectionism. These objectives outweigh any negative effect the tax may have on interstate commerce.","sumSrc":"Oyez","by":{"0":"44","1":"21","2":"passim","3":"5, 6, 7, 9, 12","4":"21"}},{"t":"case","label":"Edgar v. MITE Corp.","cite":"457 U.S. 624","y":1982,"id":"1981/80-1188","sc":1,"op":10,"ar":1,"sum":"Invalidating a nondiscriminatory state law that regulated tender offers to shareholders.","sumSrc":"opinion","by":{"0":"22, 26, 40","1":"passim","2":"19","4":"15, 23"}},{"t":"case","label":"Energy & Env’t Legal Inst. v. Epel","cite":"793 F.3d 1169","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/793/1169/","op":3,"by":{"0":"21, 35","1":"16, 22, 31","2":"passim"}},{"t":"case","label":"Exxon Corp. v. Governor of Maryland","cite":"437 U.S. 117","y":1978,"id":"1977/77-10","sc":1,"op":17,"ar":7,"sum":"No and no. In a 7-1 decision, the Court affirmed the Maryland Court of Appeals. Writing for the majority, Justice John Paul Stevens cited Ferguson v. Skrupa establishing that the purpose of the judiciary is not to \"weigh the wisdom of legislation,\" and therefore did not concern due process.","sumSrc":"Oyez","by":{"0":"50","1":"10, 28","2":"passim","4":"23"}},{"t":"case","label":"Gonzales v. Oregon","cite":"546 U.S. 243","y":2006,"id":"2005/04-623","sc":1,"sum":"The Court decided that the Controlled Substance Act did not ban the use of controlled substances in physician-assisted suicide, nor does the Attorney General have the power to determine what is a violation of the Act.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"op":2,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"H.P. Hood & Sons, Inc. v. Du Mond","cite":"336 U.S. 525","y":1949,"id":"1940-1955/336us525","sc":1,"op":1,"sum":"The Court decided that a state's business license restriction was a violation of the Commerce Clause of the Constitution where the restriction's purpose was to suppress local economic competition.","sumSrc":"Oyez","by":{"0":"25","1":"13, 23","3":"18"}},{"t":"case","label":"Hannibal & St. J.R. Co. v. Husen","cite":"95 U.S. 465","y":1877,"id":"scdb/1877-095","sc":1,"sum":"An act of the legislature of Missouri, approved Jan: 23,1872* 1 Wagner’s Stat. 251, provides as follows: —","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37, 41"}},{"t":"case","label":"Head v. N.M. Bd. of Exam’rs in Optometry","cite":"374 U.S. 424","y":1963,"id":"1962/392","sc":1,"sum":"One of the appellants owns a newspaper and the other a radio station in New Mexico close to the Texas border and much of the area served by both the newspaper and the radio station lies in Texas. Both appellants were enjoined by a New Mexico State Court from accepting or publishing within the State of New Mexico a Texas optometrist's advertising found to be in violation of a New Mexico statute regulating advertising …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Healy v. Beer Inst., Inc.","cite":"491 U.S. 324","y":1989,"id":"1988/88-449","sc":1,"op":8,"sum":"Connecticut's beer-price-affirmation statute violates the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3, 18, 21, 22, 24, 25, 26, 30, 31","1":"12, 15, 21, 23, 32, 33","2":"passim","4":"3, 8"}},{"t":"case","label":"Hill v. Colorado","cite":"530 U.S. 703","y":2000,"id":"1999/98-1856","sc":1,"sum":"The Court held that a statute requiring speakers within 100 feet of a medical facility to obtain consent before speaking, using signs, or distributing leaflets does not violate the First Amendment.","sumSrc":"Oyez","by":{"0":"36, 38"}},{"t":"case","label":"Hodel v. Va. Surface Mining & Reclamation Ass’n","cite":"452 U.S. 264","y":1981,"id":"1980/79-1538","sc":1,"sum":"In the context of a facial challenge, the Act is constitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Hughes v. Oklahoma","cite":"441 U.S. 332","y":1979,"id":"1978/77-1439","sc":1,"op":3,"sum":"The Oklahoma statute is repugnant to the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","2":"15"}},{"t":"case","label":"Kan. City S. Ry. v. Kaw Valley Drainage Dist.","cite":"233 U.S. 75","y":1914,"id":"scdb/1913-174","sc":1,"sum":"This court will read pleadings as alleging what they fairly would convey to an ordinarily intelligent lawyer by a fairly exact use of English speech. Swift & Co. v. United States, 196 ÍJ. S. 375.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Kassel v. Cons. Freightways Corp. of Del.","cite":"450 U.S. 662","y":1981,"id":"1980/79-1320","sc":1,"op":2,"ar":3,"sum":"The Court held that the law violated the Commerce Clause for two reasons. First, Iowa could not prove that the vehicles it targeted posed potential danger to highway travelers. The safety interest was \"illusory.\" Second, the law was \"out of step with the laws of all other Midwestern and Western States\" which did not have similar regulations. This placed significant burdens on the flow of interstate commerce.","sumSrc":"Oyez","by":{"0":"38, 47, 49","1":"18, 19, 25, 29, 30","4":"13"}},{"t":"case","label":"Legato Vapors, LLC v. Cook","cite":"847 F.3d 825","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/825/","ar":4,"by":{"0":"34, 39"}},{"t":"case","label":"Meyer v. Nebraska","cite":"262 U.S. 390","y":1923,"id":"1900-1940/262us390","sc":1,"op":1,"sum":"A case in which the Court struck down under the Fourteenth Amendment a Nebraska law prohibiting teachers from instructing grade school children any language other than English.","sumSrc":"Oyez","by":{"0":"37, 38"}},{"t":"case","label":"Minnesota v. Barber","cite":"136 U.S. 313","y":1890,"id":"scdb/1889-274","sc":1,"sum":"— Decided May 19, 1890.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"38, 41","2":"36"}},{"t":"case","label":"Nat’l Meat Ass’n v. Harris","cite":"565 U.S. 452","y":2012,"id":"2011/10-224","sc":1,"sum":"The Court held that a California law requiring slaughterhouses to \"immediately euthanize\" any nonambulatory animal on its premises is preempted by the Federal Meat Inspection Act.","sumSrc":"Oyez","by":{"0":"14, 43","1":"6"}},{"t":"case","label":"New State Ice Co. v. Liebmann","cite":"285 U.S. 262","y":1932,"id":"scdb/1931-090","sc":1,"op":1,"sum":"repugnant to the due process clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","2":"24"}},{"t":"case","label":"Ogden v. Saunders","cite":"25 U.S. 213","y":1827,"id":"1789-1850/25us213","sc":1,"op":1,"sum":"This is not a violation of the Contracts Clause. The state law remains controlling. The obligation of a contract made after the enactment of a bankruptcy statute is subject to the bankruptcy statute provisions. In effect, the bankruptcy statute becomes part of all subsequent contracts, limiting their obligation but not impairing them.","sumSrc":"Oyez","by":{"0":"25, 30"}},{"t":"case","label":"Pharm. Rsch. & Mfrs of Am. v. Walsh","cite":"538 U.S. 644","y":2003,"id":"2002/01-188","sc":1,"op":1,"sum":"The Court held, 9-0, that the Pharmaceutical Research and Manufacturers of America had not carried its burden of showing a probability of success on the merits of its Commerce Clause claims and, 6-3, that their showing was insufficient to support a finding that the Medicaid Act pre-empts Maine's Rx Program insofar as it threatens to coerce manufacturers into reducing their prices on non- Medicaid sales.","sumSrc":"Oyez","by":{"0":"18, 21","1":"9, 32, 33","2":"7, 19, 20"}},{"t":"case","label":"Pike v. Bruce Church, Inc.","cite":"397 U.S. 137","y":1970,"id":"1969/301","sc":1,"op":103,"ar":53,"sum":"Appellee company grows cantaloupes of superior quality in Parker, Arizona. Since the company lacks packing sheds in Parker, it transports the cantaloupes to its nearby facilities in California, where they are sorted, inspected, packed, and shipped in containers that bear the name of the California packer. Appellant official, acting under the Arizona Fruit and Vegetable Standardization Act, whi6h is designed to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 4, 5, 18, 19, 20, 23, 44, 48, 49, 50","1":"passim","2":"passim","4":"2, 21, 23"}},{"t":"case","label":"Raymond Motor Transp., Inc. v. Rice","cite":"434 U.S. 429","y":1978,"id":"1977/76-558","sc":1,"op":3,"by":{"0":"44, 47","1":"16, 24, 25, 28","4":"22"}},{"t":"case","label":"Reid v. Colorado","cite":"187 U.S. 137","y":1902,"id":"scdb/1902-007","sc":1,"sum":"The transportation of live stock from State to State is a branch of interstate commerce and any specified rule or regulation in respect of such transportation, which Congress may lawfully prescribe or authorize and which may properly be deemed a regulation of such commerce, is paramount throughout the Union.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Sentell v. New Orleans & C.R. Co.","cite":"166 U.S. 698","y":1897,"id":"scdb/1896-174","sc":1,"sum":"A state statute providing that no dog shall be entitled to the protection of the law unless placed upon the assessment rolls, and that in a civil action for killing, a dog the owner cannot recover beyond the value fixed by himself in the last assessment preceding the killing, is within the police power of the State.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"South Dakota v. Wayfair","cite":"138 S. Ct. 2080","y":2018,"id":"2017/17-494","sc":1,"op":3,"sum":"A case in which the Court overruled Quill Corp. v. North Dakota and National Bellas Hess, Inc. v. Department of Revenue of Illinois, holding that states may require sellers with no physical presence in the state to collect and remit sales tax for goods sold within the state.","sumSrc":"Oyez","by":{"0":"23, 26, 27, 32","1":"2, 12, 14, 15, 30, 31","2":"10, 11, 22","4":"5, 6, 21"}},{"t":"case","label":"Southern Pac. Co. v. State of Arizona ex rel. Sullivan","cite":"325 U.S. 761","y":1945,"id":"1940-1955/325us761","sc":1,"op":1,"sum":"The Court ruled that a state law imposing a monetary penalty on trains with more than a certain number of cars created a burden on interstate commerce that was not justified by the state's legitimate health and safety interests, and therefore the law violated the Commerce Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"26, 27, 31, 32, 37, 39","1":"14, 18, 23, 25, 26, 29","2":"19, 21, 22","3":"14","4":"3, 5, 7, 9, 13, 15, 16"}},{"t":"case","label":"Tennessee Wine & Spirits Retailers Ass’n v. Thomas","cite":"139 S. Ct. 2449","y":2019,"id":"2018/18-96","sc":1,"sum":"Tennessee’s 2-year durational-residency requirement applicable to retail liquor store license applicants violates the Commerce Clause and is not saved by the Twenty-first Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 37","1":"2, 12, 13","2":"13, 42","4":"16"}},{"t":"case","label":"United Haulers Ass’n v. Oneida-Herkimer Solid Waste Mgmt. Auth.","cite":"550 U.S. 330","y":2007,"id":"2006/05-1345","sc":1,"op":9,"sum":"Holding that the dormant Commerce Clause is not offended by higher prices “likely to fall upon the very people who voted for the [challenged] la[w]”.","sumSrc":"opinion","by":{"0":"44","1":"22","2":"passim","3":"4, 7, 8, 9","4":"13"}},{"t":"case","label":"West Lynn Creamery, Inc. v. Healy","cite":"512 U.S. 186","y":1994,"id":"1993/93-141","sc":1,"op":4,"sum":"In a majority decision authored by Justice John Paul Stevens, the Court determined that the pricing order violated the Commerce Clause because it discriminated against interstate commerce. The majority found that while the pricing order taxed all dealers, the benefit of the tax was reserved exclusively for in-state dairy farmers and outweighed the tax they were required to pay.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"0":"1","2":"passim"}},{"t":"usc","label":"7 U.S.C. § 4801","url":"https://www.law.cornell.edu/uscode/text/7/4801","subs":["(b)(3)(B)"],"stext":{"head":"§4801. Congressional findings and declaration of purpose","paras":[[0,"(a) Congress finds that—"],[1,"(1) pork and pork products are basic foods that are a valuable and healthy part of the human diet;"],[1,"(2) the production of pork and pork products plays a significant role in the economy of the United States because pork and pork products are—"],[2,"(A) produced by thousands of producers, including many small- and medium-sized producers; and"],[2,"(B) consumed by millions of people throughout the United States on a daily basis;"],[1,"(3) pork and pork products must be available readily and marketed efficiently to ensure that the people of the United States receive adequate nourishment;"],[1,"(4) the maintenance and expansion of existing markets, and development of new markets, for pork and pork products are vital to—"],[2,"(A) the welfare of pork producers and persons concerned with producing and marketing pork and pork products; and"],[2,"(B) the general economy of the United States;"],[1,"(5) pork and pork products move in interstate and foreign commerce;"],[1,"(6) pork and pork products that do not move in such channels of commerce directly burden or affect interstate commerce in pork and pork products; and"],[1,"(7) in recent years, increasing quantities of low-cost, imported pork and pork products have been brought into the United States and replaced domestic pork and pork products in normal channels of trade."],[0,"(b)(1) It is the purpose of this chapter to authorize the establishment of an orderly procedure for financing, through adequate assessments, and carrying out an effective and coordinated program of promotion, research, and consumer information designed to—"],[1,"(A) strengthen the position of the pork industry in the marketplace; and"],[1,"(B) maintain, develop, and expand markets for pork and pork products."],[0,"(2) Such procedure shall be implemented, and such program shall be conducted, at no cost to the Federal Government."],[0,"(3) Nothing in this chapter may be construed to—"],[1,"(A) permit or require the imposition of quality standards for pork or pork products;"],[1,"(B) provide for control of the production of pork or pork products; or"],[1,"(C) otherwise limit the right of an individual pork producer to produce pork and pork products."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/4801?type=usc&year=mostrecent&link-type=html"},"head":"§4801. Congressional findings and declaration of purpose","tname":"Agriculture","by":{"0":"9","2":"23"}},{"t":"usc","label":"21 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/21/601","stext":{"head":"§601. Definitions","paras":[[0,"As used in this chapter, except as otherwise specified, the following terms shall have the meanings stated below:"],[0,"(a) The term \"Secretary\" means the Secretary of Agriculture of the United States or his delegate."],[0,"(b) The term \"firm\" means any partnership, association, or other unincorporated business organization."],[0,"(c) The term \"meat broker\" means any person, firm, or corporation engaged in the business of buying or selling carcasses, parts of carcasses, meat, or meat food products of cattle, sheep, swine, goats, horses, mules, or other equines on commission, or otherwise negotiating purchases or sales of such articles other than for his own account or as an employee of another person, firm, or corporation."],[0,"(d) The term \"renderer\" means any person, firm, or corporation engaged in the business of rendering carcasses or parts or products of the carcasses, of cattle, sheep, swine, goats, horses, mules, or other equines, except rendering conducted under inspection or exemption under this subchapter."],[0,"(e) The term \"animal food manufacturer\" means any person, firm, or corporation engaged in the business of manufacturing or processing animal food derived wholly or in part from carcasses, or parts or products of the carcasses, of cattle, sheep, swine, goats, horses, mules, or other equines."],[0,"(f) The term \"State\" means any State of the United States and the Commonwealth of Puerto Rico."],[0,"(g) The term \"Territory\" means Guam, the Virgin Islands of the United States, American Samoa, and any other territory or possession of the United States, excluding the Canal Zone."],[0,"(h) The term \"commerce\" means commerce between any State, any Territory, or the District of Columbia, and any place outside thereof; or within any Territory not organized with a legislative body, or the District of Columbia."],[0,"(i) The term \"United States\" means the States, the District of Columbia, and the Territories of the United States."],[0,"(j) The term \"meat food product\" means any product capable of use as human food which is made wholly or in part from any meat or other portion of the carcass of any cattle, sheep, swine, or goats, excepting products which contain meat or other portions of such carcasses only in a relatively small proportion or historically have not been considered by consumers as products of the meat food industry, and which are exempted from definition as a meat food product by the Secretary under such conditions as he may prescribe to assure that the meat or other portions of such carcasses contained in such product are not adulterated and that such products are not represented as meat food products. This term as applied to food products of equines shall have a meaning comparable to that provided in this paragraph with respect to cattle, sheep, swine, and goats."],[0,"(k) The term \"capable of use as human food\" shall apply to any carcass, or part or product of a carcass, of any animal, unless it is denatured or otherwise identified as required by regulations prescribed by the Secretary to deter its use as human food, or it is naturally inedible by humans."],[0,"(l) The term \"prepared\" means slaughtered, canned, salted, rendered, boned, cut up, or otherwise manufactured or processed."],[0,"(m) The term \"adulterated\" shall apply to any carcass, part thereof, meat or meat food product under one or more of the following circumstances:"],[1,"(1) if it bears or contains any poisonous or deleterious substance which may render it injurious to health; but in case the substance is not an added substance, such article shall not be considered adulterated under this clause if the quantity of such substance in or on such article does not ordinarily render it injurious to health;"],[1,"(2)(A) if it bears or contains (by reason of administration of any substance to the live animal or otherwise) any added poisonous or added deleterious substance (other than one which is (i) a pesticide chemical in or on a raw agricultural commodity; (ii) a food additive; or (iii) a color additive) which may, in the judgment of the Secretary, make such article unfit for human food;"],[1,"(B) if it is, in whole or in part, a raw agricultural commodity and such commodity bears or contains a pesticide chemical which is unsafe within the meaning of section 346a of this title,"],[1,"(C) if it bears or contains any food additive which is unsafe within the meaning of section 348 of this title,"],[1,"(D) if it bears or contains any color additive which is unsafe within the meaning of section 379e of this title: Provided, That an article which is not adulterated under clause (B), (C), or (D) shall nevertheless be deemed adulterated if use of the pesticide chemical, food additive, or color additive in or on such article is prohibited by regulations of the Secretary in establishments at which inspection is maintained under this subchapter;"],[1,"(3) if it consists in whole or in part of any filthy, putrid, or decomposed substance or is for any other reason unsound, unhealthful, unwholesome, or otherwise unfit for human food;"],[1,"(4) if it has been prepared, packed, or held under insanitary conditions whereby it may have become contaminated with filth, or whereby it may have been rendered injurious to health;"],[1,"(5) if it is, in whole or in part, the product of an animal which has died otherwise than by slaughter;"],[1,"(6) if its container is composed, in whole or in part, of any poisonous or deleterious substance which may render the contents injurious to health;"],[1,"(7) if it has been intentionally subjected to radiation, unless the use of the radiation was in conformity with a regulation or exemption in effect pursuant to section 348 of this title;"],[1,"(8) if any valuable constituent has been in whole or in part omitted or abstracted therefrom; or if any substance has been substituted, wholly or in part therefor; or if damage or inferiority has been concealed in any manner; or if any substance has been added thereto or mixed or packed therewith so as to increase its bulk or weight, or reduce its quality or strength, or make it appear better or of greater value than it is; or"],[1,"(9) if it is margarine containing animal fat and any of the raw material used therein consisted in whole or in part of any filthy, putrid, or decomposed substance."],[0,"(n) The term \"misbranded\" shall apply to any carcass, part thereof, meat or meat food product under one or more of the following circumstances:"],[1,"(1) if its labeling is false or misleading in any particular;"],[1,"(2) if it is offered for sale under the name of another food;"],[1,"(3) if it is an imitation of another food, unless its label bears, in type of uniform size and prominence, the word \"imitation\" and immediately thereafter, the name of the food imitated;"],[1,"(4) if its container is so made, formed, or filled as to be misleading;"],[1,"(5) if in a package or other container unless it bears a label showing (A) the name and place of business of the manufacturer, packer, or distributor; and (B) an accurate statement of the quantity of the contents in terms of weight, measure, or numerical count: Provided, That under clause (B) of this subparagraph (5), reasonable variations may be permitted, and exemptions as to small packages may be established, by regulations prescribed by the Secretary;"],[1,"(6) if any word, statement, or other information required by or under authority of this chapter to appear on the label or other labeling is not prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or devices, in the labeling) and in such terms as to render it likely to be read and understood by the ordinary individual under customary conditions of purchase and use;"],[1,"(7) if it purports to be or is represented as a food for which a definition and standard of identity or composition has been prescribed by regulations of the Secretary under section 607 of this title unless (A) it conforms to such definition and standard, and (B) its label bears the name of the food specified in the definition and standard and, insofar as may be required by such regulations, the common names of optional ingredients (other than spices, flavoring, and coloring) present in such food;"],[1,"(8) if it purports to be or is represented as a food for which a standard or standards of fill of container have been prescribed by regulations of the Secretary under section 607 of this title, and it falls below the standard of fill of container applicable thereto, unless its label bears, in such manner and form as such regulations specify, a statement that it falls below such standard;"],[1,"(9) if it is not subject to the provisions of subparagraph (7), unless its label bears (A) the common or usual name of the food, if any there be, and (B) in case it is fabricated from two or more ingredients, the common or usual name of each such ingredient; except that spices, flavorings, and colorings may, when authorized by the Secretary, be designated as spices, flavorings, and colorings without naming each: Provided, That to the extent that compliance with the requirements of clause (B) of this subparagraph (9) is impracticable, or results in deception or unfair competition, exemptions shall be established by regulations promulgated by the Secretary;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/601?type=usc&year=mostrecent&link-type=html"},"head":"§601. Definitions","tname":"Food and Drugs","by":{"0":"14, 43","1":"1"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"reg","label":"9 C.F.R. § 309.1","url":"https://www.ecfr.gov/current/title-9/section-309.1","by":{"0":"43"}},{"t":"case","label":"American Fuel & Petrochemical Mfrs. v. O’Keeffe","cite":"903 F.3d 903","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/903/903/","by":{"1":"22"}},{"t":"case","label":"BMW of N. Am., Inc. v. Gore","cite":"517 U.S. 559","y":1996,"id":"1995/94-896","sc":1,"op":1,"sum":"In a 5-to-4 decision, the Court held that while a state may impose punitive damages to further its interest in deterring unlawful conduct, the Fourteenth Amendment's due process clause prohibits states from imposing grossly excessive punishments on tort-feasors.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Bibb v. Navajo Freight Lines, Inc.","cite":"359 U.S. 520","y":1959,"id":"1958/94","sc":1,"op":4,"ar":1,"sum":"The Court held that an Illinois trucking requirement placed an unconstitutional burden on interstate commerce.","sumSrc":"Oyez","by":{"1":"24, 29","2":"21","4":"9"}},{"t":"case","label":"Bowman v. Chicago & Nw. Ry. Co.","cite":"125 U.S. 465","y":1888,"id":"scdb/1887-187","sc":1,"sum":"The question whether, when Congress fails to provide a regulation by law as to any particular subject of commerce among the States it is conclusive of its -intention that that subject shall be free from positive regulation, or that, until Congress intervenes, it shall be left to be dealt with by the States, is one to be determined from the circumstances of each case as it arises.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Cotto Waxo Co. v. Williams","cite":"46 F.3d 790","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/46/790/","by":{"1":"22, 28"}},{"t":"case","label":"Great Atl. & Pac. Tea Co. v. Cottrell","cite":"424 U.S. 366","y":1976,"id":"1975/74-1148","sc":1,"sum":"The mandatory character of the regulation's reciprocity requirement unduly burdens the free flow of interstate commerce in violation of the Commerce Clause and cannot be justified as a permissible exercise of any state power.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24","4":"5, 19"}},{"t":"case","label":"Hunt v. Washington State Apple Adver. Comm’n","cite":"432 U.S. 333","y":1977,"id":"1976/76-63","sc":1,"op":1,"ar":2,"sum":"The Court voted unanimously that the North Carolina regulation was an unconstitutional exercise of the state's power over interstate commerce. Although the regulation was facially neutral, it had a discriminatory impact on the Washington growers while shielding the local growers from the same burden. The regulation removed the competitive advantage gained by the Washington apples from stricter inspection standards.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Maine v. Taylor","cite":"477 U.S. 131","y":1986,"id":"1985/85-62","sc":1,"op":2,"ar":3,"sum":"In an 8-to-1 decision, the Court held that the limitation imposed by the Commerce Clause on state regulatory power was not absolute and that the States \"retain[ed] authority under their general police powers to regulate matters of 'legitimate local concern.'\" The Court found that Maine's ban on the importation oflive baitfish served a legitimate local purpose that could not adequately be served by available nondiscriminatory alternatives.","sumSrc":"Oyez","by":{"1":"25","2":"35, 36, 39, 40","4":"13"}},{"t":"case","label":"Minnesota v. Clover Leaf Creamery Co.","cite":"449 U.S. 456","y":1981,"id":"1980/79-1171","sc":1,"op":1,"sum":"No and no. Writing for the majority in a 7-1 decision, Justice William J. Brennan Jr. maintained that Minnesota's statute was not unconstitutional, acknowledging that the legislature had an interest in promoting resource conservation and resolving solid waste disposal issues.","sumSrc":"Oyez","by":{"1":"22","2":"36, 48","4":"13"}},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"sum":"Appellee, a nonresident of Delaware, filed a shareholder's derivative suit in a Delaware Chancery Court, naming as defendants a corporation and its subsidiary, as well as 28 present or former corporate officers or directors, alleging that the individual defendants had violated their duties to the corporation by causing it and its subsidiary to engage in actions (which occurred in Oregon) that resulted in corporate …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Transcontinental Gas Pipe Line Corp. v. State Oil & Gas Bd. of Miss.","cite":"474 U.S. 409","y":1986,"id":"1985/84-1076","sc":1,"sum":"The Board's ratable-take order is pre-empted by the NGA and NGPA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"20","2":"42"}},{"t":"case","label":"World-Wide Volkswagen Corp. v. Woodson","cite":"444 U.S. 286","y":1980,"id":"1979/78-1078","sc":1,"sum":"The Supreme Court held that a state court could only exercise in personam jurisdiction over a non-resident defendant when that defendant has “minimum contacts” with the state. In this case, the only contact with Oklahoma was the accident.","sumSrc":"Oyez","by":{"1":"14, 20"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"21","2":"25"}},{"t":"usc","label":"7 U.S.C. § 8301","url":"https://www.law.cornell.edu/uscode/text/7/8301","by":{"1":"1"}},{"t":"usc","label":"7 U.S.C. § 8305","url":"https://www.law.cornell.edu/uscode/text/7/8305","by":{"1":"6"}},{"t":"usc","label":"21 U.S.C. § 602","url":"https://www.law.cornell.edu/uscode/text/21/602","by":{"1":"6"}},{"t":"usc","label":"21 U.S.C. § 603","url":"https://www.law.cornell.edu/uscode/text/21/603","subs":["(a)"],"by":{"1":"6"}},{"t":"usc","label":"21 U.S.C. § 604","url":"https://www.law.cornell.edu/uscode/text/21/604","by":{"1":"6"}},{"t":"case","label":"Addington v. Texas","cite":"441 U.S. 418","y":1979,"id":"1978/77-5992","sc":1,"op":1,"sum":"The Court held that the standard of proof required in a civil case involving involuntary commitment to a mental health facility must be higher than a preponderance of the evidence, but that the “beyond a reasonable doubt” standard was not constitutionally required.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Am. Beverage Ass’n v. Snyder","cite":"735 F.3d 362","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/735/362/","op":2,"sum":"Finding courts are “illequipped” to assess which types of “extraterritorial effects exceed [the] bounds” of a “ ‘practical effect’ inquiry” and “which do not”.","sumSrc":"brief:3","by":{"2":"17","3":"12"}},{"t":"case","label":"Amanda Acquisition Corp. v. Universal Foods Corp.","cite":"877 F.2d 496","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/877/496/","op":1,"sum":"Observing that Pike serves to “ `smoke out' a hidden” protectionism.","sumSrc":"opinion","by":{"2":"20"}},{"t":"case","label":"Ark. Elec. Co-op. Corp. v. Ark. Pub. Serv. Comm’n","cite":"461 U.S. 375","y":1983,"id":"1982/81-731","sc":1,"sum":"Appellant is a customer-owned rural power cooperative established with loan funds and technical assistance provided by the federal Rural Electrification Administration (REA), but unlike most such cooperatives, which provide power directly to consumers, appellant's sole members and primary customers are 17 smaller Arkansas rural power cooperatives which in turn serve the ultimate consumer. Although tied into an …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Austin v. Tennessee","cite":"179 U.S. 343","y":1900,"id":"scdb/1900-039","sc":1,"op":1,"sum":"Where cigarettes were imported in paper packages of three inches in length and one and one half in width, containing ten cigarettes, unboxed but thrown loosely into baskets: held, that such paper parcels were not original packages within-the meaning of the law, and that such importations were evidently made for the purpose of evading the law of the State prohibiting the sale of cigarettes.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"40, 42"}},{"t":"case","label":"Bell Atl. Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"op":6,"sum":"Holding that the dormant Commerce Clause is not offended by higher prices “likely to fall upon the very people who voted for the [challenged] la[w]”.","sumSrc":"opinion","by":{"2":"32, 33, 34"}},{"t":"case","label":"Breard v. City of Alexandria","cite":"341 U.S. 622","y":1951,"id":"scdb/1950-092","sc":1,"sum":"A so-called \"Green River ordinance\" of a municipality forbids the practice of going in and upon private residences for the purpose of soliciting orders for the sale of goods, without prior consent of the owners or occupants. Appellant, representing a foreign corporation, was engaged in door-to-door soliciting of subscriptions for nationally known magazines and periodicals. Subscriptions were acknowledged by a card …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46, 47"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Cavel Int’l, Inc. v. Madigan","cite":"500 F.3d 551","y":2007,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/500/551/","op":1,"by":{"2":"42, 44"}},{"t":"case","label":"Chinatown Neighborhood Ass’n v. Harris","cite":"794 F.3d 1136","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/1136/","by":{"2":"42"}},{"t":"case","label":"City of Philadelphia v. Lead Indus. Ass’n, Inc.","cite":"994 F.2d 112","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/994/112/","op":4,"by":{"2":"40"}},{"t":"case","label":"Corfield v. Coryell","cite":"6 F. Cas. 546","y":1823,"court":"C.C.E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Cas./6/546/","by":{"2":"17"}},{"t":"case","label":"CTS Corp. v. Dynamics Corp. of Am.","cite":"481 U.S. 69","y":1987,"id":"1986/86-71","sc":1,"op":1,"sum":"The federal Williams Act and implementing regulations govern hostile corporate stock tender offers by requiring, inter alia, that offers remain open for at least 20 business days. An Indiana Act applies to certain business corporations chartered in Indiana that have specified levels of shares or shareholders within the State and that opt into the Act's protection. The Indiana Act provides that the acquisition of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"passim"}},{"t":"case","label":"Day-Brite Lighting Inc. v. Missouri","cite":"342 U.S. 421","y":1952,"id":"scdb/1951-046","sc":1,"sum":"Missouri Rev. Stat., 1949, § 129.060, which provides that any employee entitled to vote may absent himself from his employment for four hours between the opening and closing of the polls on election days and that any employer who deducts wages for that absence is guilty of a misdemeanor, does not violate the Due Process or Equal Protection Clause of the Fourteenth Amendment or the Contract Clause of Art. I, § 10, of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"45"}},{"t":"case","label":"Emp. Div., Dep’t of Hum. Res. of Or. v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Empacadora de Carnes de Fresnillo, S.A. de C.V. v. Curry","cite":"476 F.3d 326","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/476/326/","by":{"2":"42"}},{"t":"case","label":"FCC v. Beach Commc’ns, Inc.","cite":"508 U.S. 307","y":1993,"id":"1992/92-603","sc":1,"sum":"The Court held that section 602(7)(B)'s common-ownership distinction is constitutional because the statutory classification neither proceeded along suspect lines nor infringed fundamental constitutional rights. \"As we have indicated,\" Justice Thomas concluded, \"there are plausible rationales unrelated to the use of public rights-of-way for regulating cable facilities serving separately owned and managed buildings.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Fort Gratiot Sanitary Landfill, Inc. v. Mich. Dep’t of Nat. Res.","cite":"504 U.S. 353","y":1992,"id":"1991/91-636","sc":1,"sum":"The Waste Import Restrictions unambiguously discriminate against interstate commerce and are appropriately characterized as protectionist measures that cannot withstand Commerce Clause scrutiny.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Gen. Motors Corp. v. Tracy","cite":"519 U.S. 278","y":1997,"id":"1996/95-1232","sc":1,"op":8,"sum":"The Court held that Ohio's differential tax treatment of natural gas sales by public utilities and independent marketers violated neither the Commerce Clause nor the Equal Protection Clause.","sumSrc":"Oyez","by":{"2":"47","3":"passim"}},{"t":"case","label":"Great Atl. & Pac. Tea Co. v. FTC","cite":"440 U.S. 69","y":1979,"id":"1978/77-654","sc":1,"sum":"A buyer who has done no more than accept the lower of two prices competitively offered does not violate § 2 (f) provided the seller has a meeting-competition defense, and here where Borden had such a defense and thus could not be liable under § 2 (b) petitioner, who did no more than accept Borden's offer, cannot be liable under § 2 (f).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Hillside Dairy Inc. v. Lyons","cite":"539 U.S. 59","y":2003,"id":"2002/01-950","sc":1,"sum":"The Court held, 8-1, that, because the Federal Agriculture Improvement and Reform Act of 1996 did not clearly express an intent to insulate California's pricing and pooling laws from a Commerce Clause challenge, the Court of Appeals erred in relying on it to dismiss the case.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Instructional Sys., Inc. v. Comput. Curriculum Corp.","cite":"35 F.3d 813","y":1994,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/35/813/","op":1,"by":{"2":"25"}},{"t":"case","label":"Lochner v. New York","cite":"198 U.S. 45","y":1905,"id":"1900-1940/198us45","sc":1,"op":1,"ar":2,"sum":"The Court held that the New York statute forbidding bakers from working more than 60 hours a week or 10 hours a day violated the Fourteenth Amendment’s right to liberty afforded to employer and employee.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Moorman Mfg. Co. v. Bair","cite":"437 U.S. 267","y":1978,"id":"1977/77-454","sc":1,"op":5,"sum":"An Iowa statute prescribes a so-called single-factor sales formula for apportioning an interstate corporation's income for state income tax purposes. Under this formula, the part of income from such a corporation's sale of tangible personal property attributable to business within the State and hence subject to the state income tax is deemed to be in that proportion which the corporation's gross sales made within …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"Murphy v. NCAA","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"N.Y., N.H. & H.R. Co. v. New York","cite":"165 U.S. 628","y":1897,"id":"scdb/1896-121","sc":1,"sum":"The statutes of New York regulating the heating of steam passenger oars, and directing guards and guard-posts to be placed on railroad bridges and trestles and the approaches thereto (paws of 1887, c. 616, Laws of 1888, c. 189), were passed in the exercise of powers resting in the State in the absence of action by Congress, and, when applied to interstate commerce, do not violate the Constitution of the United …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Nat’l Park Hosp. Ass’n v. Dep’t of Interior","cite":"538 U.S. 803","y":2003,"id":"2002/02-196","sc":1,"sum":"The Court held that the controversy was not yet ripe for judicial resolution.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"New York v. Ferber","cite":"458 U.S. 747","y":1982,"id":"1981/81-55","sc":1,"sum":"In the Court's first examination of a statute specifically targeted against child pornography, it found that the state's interest in preventing sexual exploitation of minors was a compelling \"government objective of surpassing importance.\" The law was carefully drawn to protect children from the mental, physical, and sexual abuse associated with pornography while not violating the First Amendment.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Online Merchants Guild v. Cameron","cite":"995 F.3d 540","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/995/540/","by":{"2":"28, 29, 31"}},{"t":"case","label":"Oregon v. Ice","cite":"555 U.S. 160","y":2009,"id":"2008/07-901","sc":1,"sum":"The Court found that the Sixth Amendment can assign judges, rather than juries, the responsibility of fact-finding in order to impose consecutive sentences on criminal defendants.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Paris Adult Theatre I v. Slaton","cite":"413 U.S. 49","y":1973,"id":"1972/71-1051","sc":1,"sum":"In a 5-to-4 decision, the Court held that obscene films did not acquire constitutional protection simply because they were exhibited for consenting adults only. Conduct involving consenting adults, the Court argued, was not always beyond the scope of governmental regulation.","sumSrc":"Oyez","by":{"2":"40, 42"}},{"t":"case","label":"People v. Canty","cite":"90 P.3d 1168","y":2004,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/90/1168/","by":{"2":"2"}},{"t":"case","label":"Plumley v. Massachusetts","cite":"155 U.S. 461","y":1894,"id":"1850-1900/155us461","sc":1,"sum":"The Court held that the statute did not interfere with interstate commerce but served the important function of protecting the people of Massachusetts \"against fraud and deception in the sale of food products.\" The law did not prohibit the sale of oleomargarine, just those forms of it which were colored to look like natural butter.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"2":"39"}},{"t":"case","label":"Rasmussen v. Idaho","cite":"181 U.S. 198","y":1901,"id":"scdb/1900-161","sc":1,"sum":"The provision in the statute of March 13, 1899, of Idaho that “ whenever the governor of the State of Idaho has reason to believe that scab or any other infectious disease of pheep has become epidemic in certain localities in any other State or Territory, or that conditions exist that render sheep likely to convey disease, he must thereupon by proclamation, designate such localities and prohibit the importation …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Robertson v. California","cite":"328 U.S. 440","y":1946,"id":"scdb/1945-076","sc":1,"sum":"Section 703 (a) of the California Insurance Code makes it a misdemeanor for any person, except one licensed as a \"surplus line broker,\" to act \"as agent for a nonadmitted insurer in the transaction of insurance business\" within the State. Section 1642 provides that \"A person shall not act as an insurance agent, broker, or solicitor until a license is obtained from the commissioner, authorizing such person so to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"S.C. State Highway Dep’t v. Barnwell Bros.","cite":"303 U.S. 177","y":1938,"id":"1900-1940/303us177","sc":1,"sum":"A case in which the Court upheld a state law that burdened interstate commerce because in the absence of congressional action, federal courts may not determine the details of motor vehicle regulations, as that would exceed the courts' powers.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Sable Commc’ns of Cal., Inc. v. FCC","cite":"492 U.S. 115","y":1989,"id":"1988/88-515","sc":1,"op":1,"sum":"Since the First Amendment does not protect obscene speech, as the Court found in Paris Adult Theater I v. Slaton (1973), the ban on obscene speech was legitimate. However, sexual expression that is simply indecent is protected. Thus, banning adult access to indecent messages \"far exceeds that which is necessary\" to shield minors from dial-a-porn services.","sumSrc":"Oyez","by":{"2":"35"}},{"t":"case","label":"Shelby County v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"op":2,"sum":"The Court found that Section 4 of the Voting Rights Act was unconstitutional.","sumSrc":"Oyez","by":{"2":"32"}},{"t":"case","label":"TitleMax of Del. v. Weissmann","cite":"24 F.4th 230","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/24/230/","by":{"2":"28"}},{"t":"case","label":"Tyler Pipe Indus., Inc. v. Wash. State Dep’t of Revenue","cite":"483 U.S. 232","y":1987,"id":"1986/85-1963","sc":1,"op":4,"sum":"Washington imposes a business and occupation (B & 0) tax on the privilege of engaging in business activities in the State, including manufacturing in the State and making wholesale sales in the State. The measure of the wholesale tax is the gross proceeds of sales, and the measure of the manufacturing tax is the value of the manufactured product. However, under the B & 0 tax's \"multiple activities exemption,\" local …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"case","label":"United States v. Carolene Prods. Co.","cite":"304 U.S. 144","y":1938,"id":"1900-1940/304us144","sc":1,"sum":"A case in which the Court upheld a federal law banning the interstate shipment of \"filled milk\" because Congress had a rational basis for enacting it.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"W. Union Tel. Co. v. Texas","cite":"105 U.S. 460","y":1881,"id":"scdb/1881-171","sc":1,"op":2,"ar":2,"sum":"The Western Union Telegraph Company is a New York corporation engaged in the business of.transmitting telegrams at fixed rates of compensation. Its lines extend into and through most of the States and Territories of the United States, and to Washington, in the District of Columbia. It has availed itself of the privileges and subjected itself to the obligations of title 65.of the Revised Statutes relating to …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Washington v. Davis","cite":"426 U.S. 229","y":1976,"id":"1975/74-1492","sc":1,"sum":"In a 7-to-2 decision, the Court held that the procedures and written personnel test did not constitute racial discrimination under the Equal Protection Clause. The Court found that the Clause was designed to prevent official discrimination on the basis of race; laws or other official acts that had racially disproportionate impacts did not automatically become constitutional violations.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Welton v. Missouri","cite":"91 U.S. 275","y":1876,"id":"scdb/1875-060","sc":1,"op":5,"sum":"Welton was indicted, tried, and convicted in the Circuit Court for the County of Henry, in the State of Missouri, for selling goods without a license.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"17"}},{"t":"const","label":"Article I, Section 10","clauses":[["contract-clause","Contract Clause"],["compact","Compact Clause"]],"text":"No State shall enter into any Treaty, Alliance, or Confederation; grant Letters of Marque and Reprisal; coin Money; emit Bills of Credit; make any Thing but gold and silver Coin a Tender in Payment of Debts; pass any Bill of Attainder, ex post facto Law, or Law impairing the Obligation of Contracts, or grant any Title of Nobility. No State shall, without the Consent of the Congress, lay any Imposts or Duties on Imports or Exports, except what may be absolutely necessary for executing it's inspection Laws: and the net Produce of all Duties and Imposts, laid by any State on Imports or Exports, shall be for the Use of the Treasury of the United States; and all such Laws shall be subject to the Revision and Controul of the Congress. No State shall, without the Consent of Congress, lay any Duty of Tonnage, keep Troops, or Ships of War in time of Peace, enter into any Agreement or Compact with another State, or with a foreign Power, or engage in War, unless actually invaded, or in such imminent Danger as will not admit of delay.","by":{"2":"12"}},{"t":"usc","label":"7 U.S.C. § 136a","url":"https://www.law.cornell.edu/uscode/text/7/136a","by":{"2":"40"}},{"t":"usc","label":"7 U.S.C. § 2160","url":"https://www.law.cornell.edu/uscode/text/7/2160","by":{"2":"44"}},{"t":"usc","label":"16 U.S.C. § 668","url":"https://www.law.cornell.edu/uscode/text/16/668","by":{"2":"43"}},{"t":"usc","label":"16 U.S.C. § 1538","url":"https://www.law.cornell.edu/uscode/text/16/1538","by":{"2":"43"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","by":{"2":"40"}},{"t":"reg","label":"9 C.F.R. § 412.1","url":"https://www.ecfr.gov/current/title-9/section-412.1","subs":["(c)","(e)"],"by":{"2":"4, 34, 4, 34"}},{"t":"reg","label":"Prior Label Approval System: Generic Label Approval, 78 Fed. Reg. 66,826","url":"https://www.govinfo.gov/link/fr/78/66826","by":{"2":"4"}},{"t":"reg","label":"USDA, Organic Livestock and Poultry Practices, 82 Fed. Reg. 7042","url":"https://www.govinfo.gov/link/fr/82/7042","by":{"2":"3"}},{"t":"case","label":"Am. Trucking Associations, Inc. v. Smith","cite":"496 U.S. 167","y":1990,"id":"1988/88-325","sc":1,"op":1,"sum":"A plurality of the Court held that Scheiner did not apply retroactively, and that state collection of taxes for the tax year beginning July 1, 1987, before the establishment of the escrow account, was unconstitutional.","sumSrc":"Oyez","by":{"3":"13"}},{"t":"case","label":"Edwards v. California","cite":"314 U.S. 160","y":1941,"id":"1940-1955/314us160","sc":1,"sum":"The Commerce Clause forbids a state to exclude indigents. California's interest in the health of its citizens and the sufficiency of its welfare funds do not justify the burden on interstate commerce occasioned by the law.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"McKiver v. Murphy-Brown, LLC","cite":"980 F.3d 937","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/980/937/","by":{"3":"11, 12"}},{"t":"case","label":"Nat’l Pork Producers Council v. Ross","cite":"6 F.4th 1021","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/1021/","op":8,"by":{"3":"3"}},{"t":"case","label":"Northwest Airlines, Inc. v. Minnesota","cite":"322 U.S. 292","id":"scdb/1943-066","sc":1,"op":2,"sum":"that a general Minnesota personal property tax applied to all personal property within the State and without discrimination applied on the corporation's entire fleet of airplanes did not violate the commerce clause, nor the due process clause of the Fourteenth Amendment, of the Federal Constitution. Pp. 293, 300. 213 Minn. 395, 7 N. W. 2d 691, affirmed. CERTIORARI, 319 U. S. 734, to review the affirmance of a …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"const","label":"Article I, Section 8","by":{"3":"4"}},{"t":"case","label":"Carter v. Stanton","cite":"405 U.S. 669","y":1972,"id":"1971/70-5082","sc":1,"sum":"The District Court plainly had jurisdiction, and exhaustion is not required in the circumstances of this case. Damico v. California, 389 U. S. 416. If that court's characterization of the federal question as insubstantial was based on the face of the complaint, it was error; if the court treated the motion to dismiss as one for summary judgment, its order is unilluminating as to the relevant facts or the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"1"}},{"t":"case","label":"Cooley v. Board of Wardens","cite":"53 U.S. 299","y":1851,"id":"1850-1900/53us299","sc":1,"op":6,"ar":2,"sum":"A Pennsylvania law requiring ships to hire a local pilot violates the Commerce Clause of the US Constitution.","sumSrc":"Oyez","by":{"4":"6"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"4":"14"}},{"t":"case","label":"Hughes v. Alexandria Scrap Corp.","cite":"426 U.S. 794","y":1976,"id":"1975/74-1607","sc":1,"sum":"As part of a complex plan for ridding the State of abandoned automobiles, a Maryland statute provided that anyone in possession of an inoperable automobile over eight years old (\"hulk\") could transfer it to a licensed scrap processor, who then could claim a \"bounty\" from the State for its destruction, without delivery to the processor or subsequent submission to the State of any documentation of title. In 1974 the …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"5"}},{"t":"case","label":"Parker v. Brown","cite":"317 U.S. 341","y":1943,"id":"1940-1955/317us341","sc":1,"sum":"The Court held that the program created by the California Prorate Act of 1933 was a regulation of state industry of local concern that did not impair national control over commerce. The Court noted that states had authority to regulate local matters so long as they did not materially obstruct commerce.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"Woodruff v. Parham","cite":"75 U.S. 123","y":1868,"id":"scdb/1869-015","sc":1,"op":1,"sum":"The Constitution thus ordains-:","sumSrc":"Headnote (U.S. Reports)","by":{"4":"7"}},{"t":"reg","label":"9 C.F.R. § 310.25","url":"https://www.ecfr.gov/current/title-9/section-310.25","by":{"4":"17"}},{"t":"reg","label":"USDA, Agricultural Marketing Serv., Proposed Rule to Amend Organic Livestock and Poultry Production Requirements, 87 Fed. Reg. 48,562","url":"https://www.govinfo.gov/link/fr/87/48562","by":{"4":"20"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(d)"],"by":{"4":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","subs":["(a)"],"by":{"4":"1"}}]};